	// them is `ri`'s cell h + 2. `s1 s2 s3` are scratch.
	var n int32 = port.CellsAt(ri, h)
	var maxc int32 = TrMaxComps()
	var r int32 = 0
	var nc int32 = 0
	var pid int32 = 0
	var y int32 = 0
	var x0 int32 = 0
	var x1 int32 = 0
	var root int32 = 0
	var k int32 = 0
	var q int32 = 0
	var v int32 = 0
