		trCset(cs, k, cLeft, port.CellsAt(s1, q+2))
		trCset(cs, k, cRight, port.CellsAt(s1, q+3))
		trCset(cs, k, cBottom, port.CellsAt(s1, q+4))
		trCset(cs, k, cInk, port.CellsAt(s1, q+5))
		trCset(cs, k, cNruns, port.CellsAt(s1, q+6))
